import numpy as np
from scipy import integrate

def f(x):
    return np.abs(np.abs(x) - 0.5)

def g(x):
    return np.abs(np.abs(x) - 0.25)

def h1(x):
    """y upper bound: 4*g(f(sin(2*pi*x)))"""
    return 4 * g(f(np.sin(2*np.pi*x)))

def h2(y):
    """x upper bound: 4*g(f(cos(3*pi*y)))"""
    return 4 * g(f(np.cos(3*np.pi*y)))

# Numerical integration: area = integral over [0,1]x[0,1] of 1[y<=h1(x)] * 1[x<=h2(y)]
def integrand(y, x):
    return 1.0 if (y <= h1(x) and x <= h2(y)) else 0.0

# Use double integration with fine grid
N = 4000
xs = np.linspace(0, 1, N+1)
ys = np.linspace(0, 1, N+1)
dx = 1.0/N
dy = 1.0/N

area = 0.0
for i, x in enumerate(xs[:-1]):
    xc = x + dx/2
    h1val = h1(xc)
    if h1val <= 0:
        continue
    for j, y in enumerate(ys[:-1]):
        yc = y + dy/2
        if yc <= h1val and xc <= h2(yc):
            area += dx * dy

print(f"Area (grid {N}x{N}): {area}")
