import numpy as np
from scipy import integrate

def f(x):
    return np.abs(np.abs(x) - 0.5)

def g(x):
    return np.abs(np.abs(x) - 0.25)

def h1(x):
    return 4 * g(f(np.sin(2*np.pi*x)))

def h2(y):
    return 4 * g(f(np.cos(3*np.pi*y)))

# For each x, compute the measure of y in [0, h1(x)] such that h2(y) >= x
# Use fine 1D integration for each x

def area_for_x(x):
    if x <= 0:
        return 0
    ymax = h1(x)
    if ymax <= 0:
        return 0
    # Integrate 1[h2(y) >= x] over [0, ymax]
    def indicator(y):
        return 1.0 if h2(y) >= x else 0.0
    result, _ = integrate.quad(lambda y: indicator(y), 0, ymax, limit=200, points=np.linspace(0, ymax, 500))
    return result

# Integrate over x
result, _ = integrate.quad(lambda x: area_for_x(x), 0, 1, limit=200)
print(f"Area (scipy quad): {result:.15f}")

# Check if it's a nice fraction
from fractions import Fraction
frac = Fraction(result).limit_denominator(10000)
print(f"Closest fraction (denom<=10000): {frac} = {float(frac):.15f}")
print(f"Difference: {result - float(frac):.2e}")
