def phi_mp(s):
    return 4 * abs(abs(s - mpf('0.5')) - mpf('0.25'))

def h1_mp(x):
    return phi_mp(abs(sin(2*pi*x)))

def get_h2_geq_x_intervals_mp(x_val):
    if x_val <= 0:
        return [(mpf(0), mpf(1))]
    if x_val >= 1:
        return []
    a1_ = (1 - x_val) / 4
    a2_ = (1 + x_val) / 4
    a3_ = (3 - x_val) / 4
    a4_ = (3 + x_val) / 4
    s_intervals = [(mpf(0), a1_), (a2_, a3_), (a4_, mpf(1))]
    y_intervals = []
    for (a, b) in s_intervals:
        if a >= b:
            continue
        for (c, d) in [(-b, -a), (a, b)]:
            if c > d:
                continue
            c = max(c, mpf(-1))
            d = min(d, mpf(1))
            for period_start in [mpf(0), mpf(2)/3]:
                if period_start >= 1:
                    continue
                dec_start = period_start
                dec_end = min(period_start + mpf(1)/3, mpf(1))
                y1 = dec_start + acos(d) / (3*pi)
                y2 = dec_start + acos(c) / (3*pi)
                lo = max(y1, dec_start)
                hi = min(y2, dec_end)
                if lo < hi:
                    y_intervals.append((lo, hi))
                inc_start = period_start + mpf(1)/3
                inc_end = min(period_start + mpf(2)/3, mpf(1))
                if inc_start < 1:
                    y1 = (2*pi - acos(c)) / (3*pi)
                    y2 = (2*pi - acos(d)) / (3*pi)
                    lo = max(y1, inc_start)
                    hi = min(y2, inc_end)
                    if lo < hi:
                        y_intervals.append((lo, hi))
    if not y_intervals:
        return []
    y_intervals.sort(key=lambda t: t[0])
    merged = [list(y_intervals[0])]
    for (a, b) in y_intervals[1:]:
        if a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    return [(a, b) for a, b in merged]

