    if x_val <= 0 or x_val >= 1:
        return mpf(0)
    ymax = h1_mp(x_val)
    if ymax <= 0:
        return mpf(0)
    intervals = get_h2_geq_x_intervals_mp(x_val)
    total = mpf(0)
    for (a, b) in intervals:
        lo = max(a, mpf(0))
        hi = min(b, ymax)
        if lo < hi:
            total += hi - lo
    return total

# Compute with N=500000 and N=1000000 for Richardson
for N in [500000, 1000000]:
    dx = mpf(1) / N
    total = mpf(0)
    for i in range(N):
        x = (mpf(i) + mpf('0.5')) / N
        total += area_for_x_mp(x) * dx
    print(f"N={N}: {total}")

